import numpy as np
def transforms(a):
    a=np.array(a)
    out=[]
    for m in [a,np.fliplr(a),np.flipud(a),np.flipud(np.fliplr(a)),np.rot90(a),np.rot90(a,2),np.rot90(a,3),np.rot90(a,2).T]:
        out.append(tuple(tuple(r) for r in m))
    return set(out)
